  ((select id from auth.users where email = 'demo@example.org'), 'ph-real-life-foundation', 'Real LIFE Foundation', 'Taguig', 'Philippines', 14.5509, 121.0503, 'asia', array['education', 'children']::text[], 2007, null, array['Filipino', 'English']::text[], 'partners@reallife.ph', 'https://reallife.ph', 'An Every Nation / Victory-linked foundation started in 2007 that gives scholarships, mentoring and coaching to students from poor families across the Philippines.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-action-international-ph', 'Action International Ministries Philippines', 'Silang', 'Philippines', 14.2306, 120.989, 'asia', array['work', 'children', 'discipleship']::text[], null, null, array['Filipino', 'English']::text[], null, 'https://www.actioninternational.org', 'A Christian mission that runs vocational training and discipleship for youth from poor families of Metro Manila and nearby provinces, among other ministries.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-emmanuel-international-errp', 'Emmanuel Relief and Rehabilitation Philippines (Emmanuel International)', 'Mindanao (various)', 'Philippines', 7.9, 124.9, 'asia', array['leadership', 'water', 'health']::text[], null, null, array['Cebuano', 'Filipino', 'English']::text[], null, 'https://oscar.org.uk/assets/files/jobs/program-officer-in-mindanao-philippines/2026-Philippines-Ministry-opportunity-in-Mindanao-job-description.pdf', 'The Philippine arm of Emmanuel International, partnering with local churches in Mindanao on church planting, community development (water, health, agriculture), student sponsorship and disaster relief among tribal groups.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-chosen-children-village', 'Chosen Children Village Foundation, Inc.', 'Silang', 'Philippines', 14.2439, 120.9793, 'asia', array['children', 'health', 'education']::text[], null, null, array['Filipino', 'English']::text[], 'admin@chosenchildrenfoundation.com', 'https://chosenchildrenfoundation.com/', 'A Christian residential village in Silang giving a permanent home, schooling, therapy and training to abandoned, neglected and surrendered children with physical and intellectual disabilities. The campus has cottages, a chapel, a school, a clinic and physical therapy centers.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-childrens-shelter-of-cebu', 'Children''s Shelter of Cebu', 'Cebu City', 'Philippines', 10.3297, 123.8854, 'asia', array['children', 'education', 'health']::text[], 1979, null, array['Cebuano', 'English']::text[], 'usoffice@cebushelter.org', 'https://cebushelter.org/', 'A Christ-centered ministry that has run homes for orphaned, abandoned and surrendered children in Cebu City since 1979, with medical, educational and placement services and its own school, Cebu Children of Hope School.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-kids-international-ministries', 'Kids International Ministries (KIDS)', 'Cainta', 'Philippines', 14.5786, 121.1362, 'asia', array['children', 'education', 'food']::text[], 2005, null, array['Filipino', 'English']::text[], 'serving@kidsim.org', 'https://www.kidsim.org/', 'A Christian ministry working since 2005 in the poor community of Cuatro and in Tondo, Manila. It runs children''s homes, Cuatro Christian School, a pregnancy clinic and crisis pregnancy home, and church-based feeding programs.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-tahanan-sta-luisa', 'Tahanan Sta. Luisa, Inc.', 'Antipolo', 'Philippines', 14.5865, 121.1753, 'asia', array['children', 'trauma']::text[], 1999, null, array['Filipino', 'English']::text[], null, 'https://cl.globalgiving.org/projects/tahananannualappeal/', 'A crisis intervention and recovery home for girls aged 9 to 18 rescued from the streets of Metro Manila after abuse and sexual exploitation. It provides residential care, counseling, schooling and life-skills training.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-tahanan-ng-pagmamahal', 'Tahanan ng Pagmamahal Children''s Home, Inc.', 'Pasig', 'Philippines', 14.5764, 121.0851, 'asia', array['children']::text[], null, null, array['Filipino', 'English']::text[], 'tahananpch@gmail.com', 'https://tahananngpagmamahal.org/', 'A DSWD-licensed Christian children''s home in Pasig caring for abandoned, neglected, surrendered and foundling children from infancy to early teens, with education and healthcare support.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-manaoag-christian-childrens-home', 'Manaoag Christian Children''s Home (Philippines Orphanage Foundation)', 'Manaoag', 'Philippines', 16.0439, 120.4867, 'asia', array['children', 'education']::text[], null, null, array['Filipino', 'Ilocano', 'English']::text[], 'info@filipino-orphans.org', 'https://www.filipino-orphans.org/manaoag-christian-childrens-home/', 'A small orphanage for infants and young children run with Manaoag Christian Baptist Church and funded by the US-based Philippines Orphanage Foundation (now becoming Living Hope Children''s Mission). It runs a homeschool program and has an in-house social worker.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-hospicio-de-san-jose', 'Hospicio de San Jose', 'Manila', 'Philippines', 14.5955, 120.995, 'asia', array['children', 'shelter', 'trauma']::text[], 1810, null, array['Filipino', 'English']::text[], 'admnhospiciodesanjose@gmail.com', 'https://hospiciodesanjose.org/', 'A Catholic social welfare institution run in the mission of the Daughters of Charity since 1810, on an island in the Pasig River. It cares for abandoned and neglected children, survivors of abuse and trafficking, older persons, people with special needs and people in crisis.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-preda-foundation', 'Preda Foundation (People''s Recovery, Empowerment and Development Assistance)', 'Olongapo City', 'Philippines', 14.8292, 120.2968, 'asia', array['children', 'trauma', 'legal']::text[], 1974, null, array['Filipino', 'English']::text[], null, 'https://www.preda.org/', 'Founded in 1974 by Columban missionary Fr. Shay Cullen, Preda rescues sexually abused and trafficked children and children held in jails. It runs therapeutic homes for girls and boys in Olongapo.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-mary-queen-of-heaven-missionaries', 'Mary Queen of Heaven Missionaries (Home of Love)', 'Tuburan', 'Philippines', 10.727, 123.827, 'asia', array['children', 'trauma', 'education']::text[], null, null, array['Cebuano', 'English']::text[], 'srisabel@mqhm.org', 'https://www.mqhm.org/', 'A Catholic missionary community that rescues women and girls from sex trafficking and rehabilitates them at its Home of Love in Tuburan, Cebu. Its Regina Coeli Educational Program sends rural children to school to prevent exploitation.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-wipe-every-tear', 'Wipe Every Tear', 'Angeles City', 'Philippines', 15.145, 120.5887, 'asia', array['trauma', 'education', 'food']::text[], null, null, array['Filipino', 'English']::text[], 'info@wipeeverytear.org', 'https://www.wipeeverytear.org/', 'A Christian anti-trafficking ministry that reaches women in the bars of Angeles City, runs safe homes and pays for survivors'' college education.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-noahs-ark-ministries-banaue', 'Noah''s Ark Ministries', 'Banaue', 'Philippines', 16.9136, 121.06, 'asia', array['children', 'health', 'education']::text[], null, null, array['Ifugao', 'Ilocano', 'Filipino', 'English']::text[], null, 'https://paoc.org/donate/LindaVeldhuizen', 'A children''s home in Banaue with room for up to 50 orphaned, abandoned and malnourished children. It also runs a special needs learning centre, school scholarships and infant nutrition support in Ifugao''s mountain villages.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-obeds-house-ministries', 'Obed''s House Ministries', 'General Santos City', 'Philippines', 6.1263, 125.1815, 'asia', array['children', 'discipleship']::text[], 2013, null, array['Cebuano', 'Filipino', 'English']::text[], null, 'https://give.abwe.org/projects/obed-s-house-ministries', 'A 24/7 Christian residential home in General Santos City, open since 2013, that gives neglected children aged 5 to 12 a family setting and aims to raise Christ-centered community leaders.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-little-children-of-the-philippines', 'Little Children of the Philippines (Little Children of the World)', 'Dumaguete City', 'Philippines', 9.3068, 123.2914, 'asia', array['children', 'education', 'health']::text[], null, null, array['Cebuano', 'English']::text[], null, 'https://littlechildren.org/', 'A Christ-focused ministry in Dumaguete that serves children at risk through its HELPS model: health, education, livelihood and faith programs, plus child sponsorship.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-island-kids-philippines', 'Island Kids Philippines', 'Cagayan de Oro', 'Philippines', 8.4542, 124.6179, 'asia', array['children', 'education', 'work']::text[], 2007, null, array['Cebuano', 'English']::text[], 'info@islandkids.ch', 'https://www.islandkids.ch/', 'A Swiss and German-backed charity grounded in Christian love of neighbor. Since 2007 it has run a community learning center in Cagayan de Oro for about 450 children from a waste-picker community, plus vocational training and a regenerative farm.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-shepherd-of-the-hills-baguio', 'Shepherd of the Hills Children''s Foundation', 'Baguio', 'Philippines', 16.385, 120.595, 'asia', array['children', 'education']::text[], 1976, null, array['Ilocano', 'Filipino', 'English']::text[], null, 'https://airlineamb.org/philippines-sponsorship-program/', 'A Christian children''s home on Kennon Road, Camp 7, Baguio, caring for abandoned, neglected, abused and underprivileged children since 1976.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-philippine-childrens-mission', 'Philippine Children''s Mission Inc.', 'Balagtas', 'Philippines', 14.8167, 120.9083, 'asia', array['children', 'education']::text[], 1960, null, array['Filipino', 'English']::text[], null, 'https://pcmhome.org/', 'A Christian home, running since 1960, that shelters and cares for disadvantaged children, including orphans and children of parents with leprosy or other debilitating diseases. It supports them through elementary, high school, college and life-skills training.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-silliman-university', 'Silliman University', 'Dumaguete City', 'Philippines', 9.3077, 123.3054, 'asia', array['education', 'leadership']::text[], 1901, null, array['English', 'Cebuano', 'Filipino']::text[], 'hrd@su.edu.ph', 'https://su.edu.ph', 'Protestant university founded by American Presbyterian missionaries, offering basic, college and graduate education in Dumaguete. It posts its staff and faculty openings on its own careers page.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-central-philippine-university', 'Central Philippine University', 'Iloilo City', 'Philippines', 10.7296, 122.5583, 'asia', array['education', 'health']::text[], 1905, null, array['English', 'Hiligaynon', 'Filipino']::text[], 'infocenter@cpu.edu.ph', 'https://cpu.edu.ph', 'Baptist university in Jaro, Iloilo City, founded by American Baptist missionaries. It runs colleges from social work to medicine and law, and a university church.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-faith-international-academy', 'Faith International Academy', 'Davao City', 'Philippines', 7.0852, 125.6058, 'asia', array['education', 'children']::text[], 1982, null, array['English', 'Cebuano']::text[], 'recruiting@fia.edu.ph', 'https://www.fia.edu.ph', 'Christian K-12 international school in Davao City that teaches a US-based curriculum to the children of missionaries, expatriates and local families. Its staff are largely Christian workers who raise their own support.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-doane-rest', 'Doane Rest (ABWE guesthouse)', 'Baguio City', 'Philippines', 16.4023, 120.582, 'asia', array['admin']::text[], null, null, array['English', 'Filipino']::text[], null, 'https://abwe.org/serve/opportunities/doane-rest-assistant-manager/', 'ABWE-run guesthouse and retreat center where international missionaries, Filipino pastors and other Christian workers can rest.'),
