  ((select id from auth.users where email = 'demo@example.org'), 'ph-camacop', 'Christian and Missionary Alliance Churches of the Philippines (CAMACOP)', 'General Santos City', 'Philippines', 6.1304, 125.1716, 'asia', array['shelter', 'trauma', 'food']::text[], null, null, array['Filipino', 'Cebuano', 'English']::text[], null, 'https://awf.world/awf-news/alliance-churches-respond-to-the-philippines-earthquake/', 'A national evangelical church network with over 120 years in the Philippines; its congregations in Sarangani and South Cotabato distributed food, water and hygiene kits and offered trauma counseling after the June 2026 earthquake.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-uccp-cares', 'UCCP CARES (United Church of Christ in the Philippines Aid and Relief Services)', 'General Santos City', 'Philippines', 6.1263, 125.1617, 'asia', array['refugees', 'shelter', 'trauma']::text[], 2013, null, array['Filipino', 'Cebuano', 'English']::text[], null, 'https://www.vemission.org/en/details/earthquake-relief-for-the-philippines-uem-and-regional-churches-pledge-eur50000-in-emergency-aid-to-local-church', 'The disaster response ministry of the United Church of Christ in the Philippines, formed after Typhoon Haiyan, now supplying food, shelter, medical and psychosocial care to Sarangani earthquake survivors.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-nccp', 'National Council of Churches in the Philippines (NCCP)', 'Alabel', 'Philippines', 6.1028, 125.2906, 'asia', array['refugees', 'food', 'trauma']::text[], 1963, null, array['Filipino', 'Cebuano', 'English']::text[], null, 'https://actalliance.org/?p=278260', 'An ecumenical council of Protestant and independent churches and an ACT Alliance member, running cash, food, WASH and psychosocial assistance for families displaced by the June 2026 Mindanao earthquake.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-mustard-seed-mission-ph', 'The Mustard Seed Mission (Philippines earthquake response)', 'General Santos City', 'Philippines', 6.1164, 125.1576, 'asia', array['shelter', 'children', 'work']::text[], 1952, null, array['Filipino', 'Cebuano', 'English']::text[], 'service@mustard.org.tw', 'https://fil.benevity.org/community/cause/158-5869958163392_000c/project/65VQCD342P', 'A Christian relief mission founded in 1952 that, with local partners PHILRADS, SEND International and church networks, is running a three-phase relief-to-rebuilding program after the 2026 Mindanao earthquake.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-wesleyan-church-philippines-2', 'The Wesleyan Church of the Philippines (Southern Mindanao District)', 'General Santos City', 'Philippines', 6.1065, 125.1617, 'asia', array['shelter', 'food', 'worship']::text[], null, null, array['Filipino', 'Cebuano', 'English']::text[], null, 'https://www.wesleyan.org/philippines-earthquake-response-stand-with-our-wesleyan-family', 'A Wesleyan denomination whose Southern Mindanao District lost six church buildings and its district center in the June 2026 earthquake and is clearing sites while distributing water and rice to members and neighbors.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-nazarene-philippines', 'Church of the Nazarene Philippines (Nazarene Compassionate Ministries)', 'General Santos City', 'Philippines', 6.1024, 125.1716, 'asia', array['shelter', 'children', 'trauma']::text[], null, null, array['Filipino', 'Cebuano', 'T''boli']::text[], 'info@nazarene.org', 'https://nazarene.org/?p=74491', 'Nazarene congregations in General Santos City and T''boli, with the church''s compassionate ministries arm, providing food, children''s care and shelter rehabilitation after earthquakes and typhoons.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-adra-philippines', 'ADRA Philippines (Adventist Development and Relief Agency)', 'Silang', 'Philippines', 14.2173, 120.9793, 'asia', array['refugees', 'health', 'work']::text[], null, null, array['Filipino', 'English']::text[], null, 'https://adra.ph/', 'The Seventh-day Adventist Church''s humanitarian agency in the Philippines, working in emergency response, health, education and livelihoods.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-habitat-philippines', 'Habitat for Humanity Philippines', 'Makati City', 'Philippines', 14.5547, 121.0244, 'asia', array['shelter', 'education']::text[], null, null, array['Filipino', 'English']::text[], 'info@habitat.org.ph', 'https://www.habitat.org.ph/', 'The Philippine affiliate of the Christian housing ministry, building disaster-resilient core shelters, providing shelter repair after disasters and training communities in preparedness.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-samaritans-purse-cebu', 'Samaritan''s Purse (Cebu earthquake response)', 'Bogo City', 'Philippines', 11.0517, 124.0058, 'asia', array['shelter', 'food']::text[], null, null, array['Cebuano', 'Filipino', 'English']::text[], null, 'https://samaritanspurse.org/article/serving-earthquake-rattled-families-in-philippines', 'Christian relief organization working through local churches and Operation Christmas Child networks in Bogo, Tabogon and San Remigio, distributing shelter kits, food and hygiene kits after the September 2025 Cebu earthquake.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-operation-blessing-ph-2', 'Operation Blessing (Philippines)', 'Cebu City', 'Philippines', 10.3017, 123.8854, 'asia', array['food', 'water', 'health']::text[], null, null, array['Cebuano', 'Filipino', 'English']::text[], null, 'https://ob.org/philippines-earthquake/', 'Christian humanitarian organization whose Philippine team delivered meals, water filtration, hygiene kits, medical care and psychological first aid in Cebu after the 2025 earthquake and typhoons.'),
  ((select id from auth.users where email = 'demo@example.org'), 'ph-philrads', 'Philippine Relief and Development Services (PHILRADS)', 'General Santos City', 'Philippines', 6.1065, 125.1815, 'asia', array['shelter', 'refugees', 'trauma']::text[], null, null, array['Filipino', 'Cebuano', 'English']::text[], null, 'https://peacebuilderscommunity.org/peacebuilding,peace,reconciliation/philrads/', 'The relief and development arm of the Philippine Council of Evangelical Churches, assessing needs and deploying relief with local churches in the 2026 Mindanao earthquake zone.'),
