  ('ph-working-hands-cavite', 'Trade-skills discipleship intern', 'volunteers', 'ongoing', 1, 'work', false, 'Internship', array['Woodworking/trades', 'Mentoring']::text[], 'Use your trade skills to build relationships with Working Hands students, encouraging them in faith while helping train them in a vocational skill.

Source: https://www.actioninternational.org/opportunities-detail/philippines-working-hands-discipleship-internship', '2026-10-06'),
  ('ph-shalom-birthing-home', 'Midwife', 'expertise', 'ongoing', 1, 'health', false, 'Long-term', array['Midwifery', 'Prenatal/postnatal care', 'Record keeping']::text[], 'Midwives are needed for prenatal and postnatal check-ups, labor and delivery support and patient records at Shalom Christian Birthing Home, sharing the gospel with poor mothers.

Source: https://www.actioninternational.org/opportunities-detail/philippines-shalom-midwife', '2026-10-06'),
  ('ph-shalom-birthing-home', 'Nursing / global health intern', 'volunteers', 'ongoing', 1, 'health', false, 'Internship', array['Nursing', 'Patient education']::text[], 'Interns join Shalom''s medical staff in outpatient maternity care (prenatal, postnatal, newborn checks, patient education) and rotate with other medical ministries.

Source: https://www.actioninternational.org/opportunities-detail/philippines-shalom-nursing-internship-opportunity', '2026-10-06'),
  ('ph-action-project-pagasa', 'K-10 teachers (math, English, science, Filipino, PE, arts)', 'expertise', 'ongoing', 0, 'education', false, 'At least one school year recommended', array['Education degree', 'Trauma-sensitive teaching']::text[], 'Teaching positions are open for grades K-10 in math, English, science, Filipino, Filipino history, PE, art and music, working with a lead teacher and students with high learning needs.

Source: https://www.actioninternational.org/opportunities-detail/philippines-teacher-at-project-pagasa', '2026-10-06'),
  ('ph-action-iloilo-island', 'Island ministry intern', 'volunteers', 'ongoing', 1, 'discipleship', false, 'Internship', array['Language learning', 'Evangelism']::text[], 'Interns first learn language and culture, then join discipleship and evangelism in a typhoon resettlement community and on remote islands.

Source: https://www.actioninternational.org/opportunities-detail/philippines-internship-in-island-ministry', '2026-10-06'),
  ('ph-omf-philippines-field', 'Volunteer Coordinator', 'expertise', 'ongoing', 1, 'admin', false, '1-3+ years', array['Administration', 'Volunteer management', 'English']::text[], 'Build OMF Philippines'' volunteer program: recruit, onboard and place local and expat volunteers with the Field Director and strategy leaders. Listed with a March 2026 start.

Source: https://opportunities.omf.org/opportunity-detail/?id=1609', '2026-10-06'),
  ('ph-omf-philippines-field', 'Human Resources Personnel Manager', 'expertise', 'ongoing', 1, 'admin', false, '1-3+ years', array['HR strategy', 'Recruitment', 'Personnel admin']::text[], 'Plan and run HR policies, recruitment and personnel administration for the OMF Philippines field team of missionaries, employees and volunteers.

Source: https://opportunities.omf.org/opportunity-detail/?id=1610', '2026-10-06'),
  ('ph-omf-philippines-field', 'Field Medical Advisor (doctor)', 'expertise', 'ongoing', 1, 'health', false, '1-3+ years', array['General medicine', 'Occupational health']::text[], 'A doctor with general medical experience is needed to give medical advice, screening and reviews to 50+ OMF members and children in the Philippines.

Source: https://opportunities.omf.org/opportunity-detail/?id=1637', '2026-10-06'),
  ('ph-omf-philippines-field', 'Seminary theological educator', 'expertise', 'ongoing', 0, 'education', false, '1-3+ years', array['Theology', 'Preaching', 'Teaching']::text[], 'Teach theology, ministry, preaching and leadership at partner schools such as AGST, Biblical Seminary of the Philippines, Asian Theological Seminary and Koinonia Theological Seminary, and mentor students.

Source: https://opportunities.omf.org/opportunity-detail/?id=1435', '2026-10-06'),
  ('ph-omf-philippines-field', 'Non-formal theological trainer and mentor', 'expertise', 'ongoing', 0, 'leadership', false, '1-3+ years', array['Teaching', 'Mentoring', 'Curriculum']::text[], 'Train and mentor current and future church leaders through informal theological education in local churches and evangelical networks, mostly in rural areas.

Source: https://opportunities.omf.org/opportunity-detail/?id=1433', '2026-10-06'),
  ('ph-omf-philippines-field', 'Church planters for urban and rural communities', 'volunteers', 'ongoing', 0, 'discipleship', false, '1-3+ years', array['Evangelism', 'Discipleship', 'Community development']::text[], 'Serve alongside partner churches to share the gospel, disciple believers and meet practical needs in education, health and livelihood.

Source: https://opportunities.omf.org/opportunity-detail/?id=1623', '2026-10-06'),
  ('ph-omf-philippines-field', 'Provincial college ministry worker', 'volunteers', 'ongoing', 0, 'discipleship', false, '1-3+ years', array['Student ministry', 'Bible study leading']::text[], 'Join mostly Filipino teams in the provinces to evangelize and disciple college students and connect them with local churches.

Source: https://opportunities.omf.org/opportunity-detail/?id=1624', '2026-10-06'),
  ('ph-omf-philippines-field', 'Professionals: health, teaching, ethnoarts & livelihood', 'expertise', 'ongoing', 0, 'work', false, '1-3+ years', array['Healthcare', 'Ethnomusic/ethnoarts', 'Agriculture', 'Finance']::text[], 'OMF seeks people with skills in healthcare, nutrition, teaching, horticulture, finance, counseling, music, art and sport to live among and serve communities; ethnoarts and ethnomusic skills are especially wanted.

Source: https://opportunities.omf.org/opportunity-detail/?id=1626', '2026-10-06'),
  ('ph-omf-philippines-field', 'Media creator & content team', 'expertise', 'ongoing', 0, 'media', false, '6 months to 3+ years', array['Photography', 'Video', 'Writing', 'Social media']::text[], 'Visual storytellers, writers, photographers and video producers are needed to tell what God is doing in the Philippines for mobilization campaigns and events.

Source: https://opportunities.omf.org/opportunity-detail/?id=1518', '2026-10-06'),
  ('ph-omf-philippines-field', 'Serve Asia short-term missions coordinator', 'expertise', 'ongoing', 1, 'admin', false, '1-3+ years', array['Mobilization', 'Screening', 'Pastoral care']::text[], 'Screen, prepare, receive and debrief short-term workers serving under a year in the Philippines. The role is based in Manila or Davao.

Source: https://opportunities.omf.org/opportunity-detail/?id=1520', '2026-10-06'),
  ('ph-caritas-philippines', 'Relief and rehabilitation fund for Mindanao quake survivors', 'funding', 'soon', 0, 'refugees', true, 'one-off gift', '{}', 'After the June 8, 2026 magnitude 7.8 earthquake off Sarangani, the bishops'' conference asked parishes and Catholic institutions to give toward emergency relief and reconstruction. Funds are routed through diocesan social action centers and Caritas Philippines for affected communities in Sarangani, General Santos and the Lake Sebu area.

Source: https://fides.org/en/news/77776', '2026-10-06'),
  ('ph-caritas-philippines', 'Recovery support for typhoon and quake families in Masbate and Cebu', 'funding', 'ongoing', 0, 'shelter', true, 'one-off gift', '{}', 'Caritas Philippines and Caritas Masbate are helping about 1,600 families recover from late-2025 typhoons and the Cebu earthquake with rice, shelter repair vouchers, household items, cash aid and replacement tools for farmers and fisherfolk. The update stresses that recovery will take time and links a donation page for continued support.

Source: https://www.caritas.org/philippines/emergency/caritas-philippines-responds-as-communities-recover-from-multiple-disasters/', '2026-03-18'),
  ('ph-caritas-philippines', 'Join the Alay Kapwa donor community', 'partners', 'ongoing', 0, 'fundraising', true, 'monthly giving', '{}', 'Caritas Philippines invites individuals to sign up for its ''Be 1N A Million'' Alay Kapwa donor program, the standing support base for its disaster response and social action work. Sign-up is by an online form, and questions go to its communications office.

Source: https://caritas.org.ph/alay-kapwa/be-1n-a-million/', '2026-10-06'),
  ('ph-diocese-legazpi-sac', 'Cash donations for Mayon eruption evacuees', 'funding', 'soon', 0, 'refugees', true, 'one-off gift', '{}', 'After Mayon Volcano''s May 3, 2026 eruption affected some 195,000 people in Guinobatan, Camalig, Oas and Ligao City, the diocese''s Social Action Center appealed for cash to support families in evacuation centers. Gifts go to the Social Action Center''s bank account or GCash, with proof of transfer sent via its Facebook page.

Source: https://interaksyon.philstar.com/politics-issues/2026/05/05/312895/legazpi-diocese-launches-urgent-aid-drive-as-mayon-unrest-displaces-thousands/', '2026-05-05'),
  ('ph-diocese-legazpi-sac', 'Food, water and face masks for ash-hit evacuation centers', 'supplies', 'soon', 0, 'food', false, null, '{}', 'The Social Action Center asked for in-kind donations of food, drinking water and face masks for families displaced by Mayon ashfall. The drop-off point is the Social Action Center at the Albay Cathedral compound in Legazpi City.

Source: https://interaksyon.philstar.com/politics-issues/2026/05/05/312895/legazpi-diocese-launches-urgent-aid-drive-as-mayon-unrest-displaces-thousands/', '2026-05-05'),
  ('ph-diocese-marbel-sac', 'Earthquake relief for Marbel diocese and Lake Sebu communities', 'funding', 'soon', 0, 'refugees', true, 'one-off gift', '{}', 'The Diocese of Marbel''s social action center is the main channel for church relief to General Santos City, South Cotabato and Sarangani after the 2026 quake. Some indigenous communities around Lake Sebu were still hard to reach, and other dioceses were sending money directly to Marbel to support relief and rehabilitation.

Source: https://fides.org/en/news/77776', '2026-10-06'),
  ('ph-camacop', 'Rebuild homes for quake families still living in tents', 'funding', 'urgent', 0, 'shelter', true, 'one-off gift', '{}', 'CAMACOP reports that many families in Sarangani, South Cotabato and General Santos City are still in tents after the June 2026 earthquake. Rebuilding homes is listed as a critical ongoing need, and gifts are received through the Alliance World Fellowship giving page.

Source: https://awf.world/awf-news/alliance-churches-respond-to-the-philippines-earthquake/', '2026-10-06'),
  ('ph-camacop', 'Reconstruct 16+ quake-damaged Alliance church buildings', 'funding', 'soon', 0, 'worship', true, 'one-off gift', '{}', 'More than 16 CAMACOP church buildings in the earthquake zone (Glan, Camahual, Butulan and other communities) were damaged. Rebuilding them is listed among the critical ongoing needs.

Source: https://awf.world/awf-news/alliance-churches-respond-to-the-philippines-earthquake/', '2026-10-06'),
  ('ph-camacop', 'Solar lighting for quake-hit communities without power', 'supplies', 'soon', 0, 'shelter', false, null, '{}', 'With roads and electricity still under repair in parts of Sarangani, CAMACOP lists solar lighting for affected communities as an ongoing need.

Source: https://awf.world/awf-news/alliance-churches-respond-to-the-philippines-earthquake/', '2026-10-06'),
  ('ph-camacop', 'Restore schools and livelihoods after the Sarangani quake', 'funding', 'ongoing', 0, 'work', true, 'one-off gift', '{}', 'Alongside housing and church rebuilding, CAMACOP names restoring schools and family livelihoods as a longer-term recovery need for the communities it serves.

Source: https://awf.world/awf-news/alliance-churches-respond-to-the-philippines-earthquake/', '2026-10-06'),
  ('ph-uccp-cares', 'Emergency relief fund for Sarangani earthquake survivors', 'funding', 'soon', 0, 'refugees', true, 'one-off gift', '{}', 'UCCP CARES is distributing food, water, hygiene kits, blankets, sleeping mats and clothing and providing medical and psychosocial care, with a focus on children, pregnant women, the elderly and people with disabilities. Partner churches abroad (UEM in Germany, PC(USA) via Presbyterian Disaster Assistance) are collecting gifts for this response.

Source: https://www.vemission.org/en/details/earthquake-relief-for-the-philippines-uem-and-regional-churches-pledge-eur50000-in-emergency-aid-to-local-church', '2026-10-06'),
  ('ph-uccp-cares', 'Temporary shelters and solar power for displaced families', 'supplies', 'soon', 0, 'shelter', false, null, '{}', 'Part of the UCCP response is setting up temporary shelters and installing solar power systems for light and communication in communities where water and electricity were cut and roads damaged. Several UCCP sanctuaries in the region were also severely damaged.

Source: https://pcusa.org/news-storytelling/news/2026/6/17/pcusa-responds-powerful-earthquake-philippines', '2026-06-17'),
  ('ph-nccp', 'Food packs and safe drinking water for displaced families', 'supplies', 'soon', 0, 'food', false, null, '{}', 'The NCCP''s assessment through local ecumenical groups put food assistance and safe drinking water at the top of the priority needs. More than 40,000 people were displaced across 163 barangays in Regions IX, XI and XII.

Source: https://actalliance.org/?p=278260', '2026-10-06'),
  ('ph-nccp', 'Hygiene kits and sleeping materials for evacuees', 'supplies', 'soon', 0, 'refugees', false, null, '{}', 'Essential non-food items, specifically hygiene kits and sleeping materials, were among the priority needs the NCCP identified for families displaced by the Mindanao earthquake.

Source: https://actalliance.org/?p=278260', '2026-10-06'),
  ('ph-nccp', 'Temporary shelter for families displaced by the quake', 'funding', 'soon', 0, 'shelter', true, 'one-off gift', '{}', 'Temporary shelter for displaced households is listed among the NCCP''s priority needs. Donations reach the response through ACT Alliance members such as the United Church of Canada, where 85% of each gift goes to this crisis.

Source: https://united-church.ca/social-action/act-now/philippines-earthquake-relief', '2026-10-06'),
  ('ph-nccp', 'Psychosocial support and protection for women and children', 'expertise', 'soon', 0, 'trauma', false, null, array['Psychosocial support', 'Child protection', 'Cebuano']::text[], 'The NCCP lists psychosocial support and protection services, especially for women and children, as a priority need after the earthquake. Psychosocial support is one of the four activities in its ACT Rapid Response Fund response, alongside cash, food and WASH.

Source: https://actalliance.org/?p=278297', '2026-10-06'),
  ('ph-nccp', 'WASH services in earthquake-affected barangays', 'funding', 'ongoing', 0, 'water', true, 'one-off gift', '{}', 'Water, sanitation and hygiene services are a core part of the NCCP''s earthquake response, which received USD 149,000 from the ACT Rapid Response Fund for about 32,900 affected families.

Source: https://actalliance.org/?p=278297', '2026-10-06'),
  ('ph-mustard-seed-mission-ph', 'Transitional housing for 150 displaced households', 'funding', 'soon', 0, 'shelter', true, 'one-off gift', '{}', 'Phase 2 of the Mustard Seed Mission response plans shelter support and the construction of medium-term transitional housing for 150 earthquake-affected families, coordinated with PHILRADS and local churches. The full three-phase budget is about NT$10.6 million (~USD 325,000).

Source: https://fil.benevity.org/community/cause/158-5869958163392_000c/project/65VQCD342P', '2026-10-06'),
  ('ph-mustard-seed-mission-ph', 'Home repairs for 55 quake-damaged households', 'funding', 'ongoing', 0, 'shelter', true, 'one-off gift', '{}', 'The recovery and rebuilding phase includes repairing homes for 55 households damaged in the 2026 Mindanao earthquake.

Source: https://fil.benevity.org/community/cause/158-5869958163392_000c/project/65VQCD342P', '2026-10-06'),
  ('ph-mustard-seed-mission-ph', 'Cash-for-work jobs for 40 earthquake-affected residents', 'funding', 'ongoing', 0, 'work', true, 'one-off gift', '{}', 'Phase 3 plans a cash-for-work program employing 40 local residents in recovery work, so families can earn income while their communities rebuild.

Source: https://fil.benevity.org/community/cause/158-5869958163392_000c/project/65VQCD342P', '2026-10-06'),
  ('ph-mustard-seed-mission-ph', 'Education kits for 300 children affected by the quake', 'supplies', 'ongoing', 0, 'children', false, null, '{}', 'The plan includes education kits (stationery, school bags and books) for 300 children whose schooling was disrupted. Earlier phases trained 20 local volunteers to accompany 500 affected children with psychosocial support.

Source: https://fil.benevity.org/community/cause/158-5869958163392_000c/project/65VQCD342P', '2026-10-06'),
  ('ph-wesleyan-church-philippines-2', 'Rebuild six destroyed churches and a district center', 'funding', 'soon', 0, 'worship', true, 'one-off gift', '{}', 'Six Wesleyan churches and one district center in Southern Mindanao were destroyed by the June 2026 earthquake, and demolition and cleanup have begun. The denomination''s Global Partners Emergency Relief Fund (about $6,750 raised by June 18) supports reconstruction and recovery.

Source: https://www.wesleyan.org/philippines-earthquake-response-stand-with-our-wesleyan-family', '2026-06-18'),
  ('ph-wesleyan-church-philippines-2', 'Temporary worship spaces for congregations that lost buildings', 'supplies', 'soon', 0, 'worship', false, null, '{}', 'Congregations whose sanctuaries were demolished need temporary places to worship while rebuilding plans move forward.

Source: https://www.wesleyan.org/philippines-earthquake-response-stand-with-our-wesleyan-family', '2026-06-18'),
  ('ph-wesleyan-church-philippines-2', 'Practical relief for church members and neighbors', 'funding', 'ongoing', 0, 'food', true, 'one-off gift', '{}', 'District teams are distributing bottled water, rice and other supplies to church members and surrounding communities. The relief fund supports this practical aid to affected congregants.

Source: https://www.wesleyan.org/philippines-earthquake-response-stand-with-our-wesleyan-family', '2026-06-18'),
  ('ph-nazarene-philippines', 'Repair T''boli church building and quake-cracked parsonage', 'funding', 'soon', 0, 'worship', true, 'one-off gift', '{}', 'In T''boli, South Cotabato, the unfinished Nazarene church building suffered structural damage and is at risk of collapse, and the pastor''s parsonage has cracked flooring and a damaged pillar. The region asks for continued disaster response support.

Source: https://nazarene.org/?p=74491', '2026-10-06'),
  ('ph-nazarene-philippines', 'Shelter rehabilitation for General Santos daycare families', 'funding', 'soon', 0, 'shelter', true, 'one-off gift', '{}', 'More than 100 families linked to the General Santos City Church of the Nazarene daycare ministry had homes damaged or destroyed. The church is providing shelter care and rehabilitation help for about 120 community members, along with food packs and child-focused activities.

Source: https://nazarene.org/?p=74491', '2026-10-06'),
  ('ph-nazarene-philippines', 'Philippines Disaster Response fund: food, water, shelter, trauma care', 'funding', 'ongoing', 0, 'trauma', true, 'one-off gift', '{}', 'Nazarene Compassionate Ministries runs a Philippines disaster response fund for local churches responding to typhoons, earthquakes, fires and floods in Cebu, Masbate, Mindoro and Taytay, Rizal. It covers food, clean water, shelter and trauma care.

Source: https://give.ncm.org/donate/140130', '2025-11-01'),
  ('ph-adra-philippines', 'Give to ADRA Philippines'' emergency fund', 'funding', 'ongoing', 0, 'refugees', true, 'one-off gift', '{}', 'ADRA Philippines asks for gifts to its emergency fund, which pays for immediate disaster assistance, recovery work and building local resilience to future shocks.

Source: https://adra.ph/disaster-response/', '2026-10-06'),
  ('ph-adra-philippines', 'COLMEAL Officer (Hub)', 'expertise', 'urgent', 1, 'admin', false, 'staff role', array['Monitoring & evaluation', 'Accountability', 'Learning']::text[], 'ADRA Philippines is hiring a COLMEAL Officer for its hub team at the Silang, Cavite office. Applications close October 9, 2026, and full requirements are in the linked job specification.

Source: https://adra.ph/get-involved/join-our-team/', '2026-10-06'),
  ('ph-habitat-philippines', 'Juan Build volunteers for house construction days', 'volunteers', 'ongoing', 0, 'shelter', false, 'half-day or full day', array['Construction']::text[], 'Habitat Philippines'' Juan Build program places volunteers on half-day or full-day construction work in Habitat communities. Groups and individuals sign up through the online volunteer form.

Source: https://www.habitat.org.ph/build-with-us', '2026-10-06'),
  ('ph-habitat-philippines', 'Juan Brigade trainers for financial literacy and health', 'expertise', 'ongoing', 0, 'education', false, null, array['Financial literacy', 'Leadership training', 'Health education']::text[], 'The Juan Brigade program asks volunteers to run community development activities beyond construction, such as leadership seminars, financial literacy training and health programs for Habitat homeowner communities.

Source: https://www.habitat.org.ph/build-with-us', '2026-10-06'),
  ('ph-habitat-philippines', 'Support disaster shelter repair and resilient core homes', 'funding', 'ongoing', 0, 'shelter', true, 'one-off gift', '{}', 'Habitat Philippines'' disaster response provides shelter repair kits, tools, materials and trained carpenters right after disasters. It then builds disaster-resilient core shelters in safer areas and runs preparedness training, and it invites individuals and organizations to fund this work.

Source: https://www.habitat.org.ph/disaster-response', '2026-10-06'),
  ('ph-samaritans-purse-cebu', 'Shelter, food and water for northern Cebu quake survivors', 'funding', 'ongoing', 0, 'shelter', true, 'one-off gift', '{}', 'Working with local churches in Bogo, Tabogon and San Remigio, Samaritan''s Purse has given shelter kits to 2,700+ families and food to over 2,000, as many stayed displaced through the monsoon season. Gifts to its International Emergency Relief fund cover immediate needs and longer-term recovery.

Source: https://samaritanspurse.org/article/serving-earthquake-rattled-families-in-philippines', '2026-10-06'),
  ('ph-operation-blessing-ph-2', 'Philippines earthquake and typhoon relief gifts', 'funding', 'ongoing', 0, 'water', true, 'one-off or monthly gift', '{}', 'Operation Blessing asks for one-time or monthly gifts for families in Cebu hit by the 6.9 earthquake and later typhoons. Its local team provides meals, water filtration, hygiene kits, solar lamps, medical supplies and psychological first aid.

Source: https://ob.org/philippines-earthquake/', '2026-10-06'),
  ('ph-philrads', 'Rebuild homes and church sanctuaries in the Mindanao quake zone', 'funding', 'soon', 0, 'shelter', true, 'one-off gift', '{}', 'PHILRADS is the ground partner for assessments and relief after the June 2026 earthquake, where local churches turned sanctuaries into evacuation centers. The partner appeal (via International Christian Concern) seeks funds to rebuild homes, repair damaged churches and give trauma support to survivors.

Source: https://persecution.org/2026/06/09/offshore-earthquake-rocks-southern-mindanao/', '2026-06-09'),
  ('ph-archdiocese-cebu', 'Restore Sta. Rosa de Lima shrine and aid Daanbantayan survivors', 'funding', 'ongoing', 0, 'shelter', true, 'one-off gift', '{}', 'Archbishop Alberto Uy appealed for financial and in-kind support after the archdiocesan shrine of Sta. Rosa de Lima in Daanbantayan was heavily damaged in the September 2025 quake. Restoration of nine damaged northern Cebu churches is slated for 2026, and parishes say they cannot carry the costs alone.

Source: https://www.sunstar.com.ph/cebu/rehab-of-quake-hit-churches-in-north-cebu-set-for-2026', '2026-10-06'),
  ('ph-archdiocese-cebu', 'Parishes to ''adopt'' quake-hit parishes in northern Cebu', 'partners', 'ongoing', 0, 'refugees', false, null, '{}', 'The archbishop urged unaffected parishes to adopt earthquake-hit parishes and send them steady relief and help with recovery. He also asked parish priests to raise funds and in-kind donations for survivors.

Source: https://philippines.licas.news/2025/10/01/cebu-archbishop-appeals-for-aid-after-sta-rosa-de-lima-shrine-destroyed-in-quake/', '2025-10-01')
) as v(slug, title, type, urgency, people, focus, remote, commitment, skills, detail, posted)
join public.ministries m on m.slug = v.slug;

commit;
